-- Shared base food database (user_id is null). Values per 100 g of the stated state.
-- Sources:
--   usda_sr  = USDA FoodData Central, SR Legacy (public domain / CC0); source_ref = NDB number
--   ru_table = Russian composition tables (Skurikhin & Tutelyan, "Химический состав
--              российских пищевых продуктов") and typical EAEU labels — used for
--              products that differ from US analogues (tvorog, kefir, smetana, bread)
--   kz       = Central Asian / Kazakh dishes: home/canteen recipes vary a lot, so
--              every row carries an honest kcal range (kcal_low_100g..kcal_high_100g)
--              and confidence 'low'/'medium'
--   seed     = generic estimates (e.g. "typical whey protein") — check your label
-- Raw vs cooked: separate rows; cooked rows link to raw rows via raw_food_id and
-- yield_factor = cooked weight / raw (or dry) weight.

insert into public.foods (
  source, source_ref, name_ru, name_en, aliases, category, state,
  kcal_100g, protein_100g, fat_100g, carbs_100g, fiber_100g,
  kcal_low_100g, kcal_high_100g, yield_factor, default_portion_g, portions, confidence, notes
) values
