-- Link cooked rows to their raw/dry counterparts (for raw<->cooked conversion).
update public.foods c set raw_food_id = r.id
from public.foods r
where c.user_id is null and r.user_id is null and (c.source, c.source_ref, r.source, r.source_ref) in (
  ('usda_sr','05064','usda_sr','05062'),
  ('usda_sr','05066','usda_sr','05062'),
